// Generated by `factory render`. Do not edit.
// The redaction boundary (owner requirement, dogfood C23: an employer's scanner read a committed factory record as a
// posted API key). Everything the harness and the agents write or publish passes through here: metrics shards, run
// records, decisions, usage rows, transcript excerpts, logs, lessons, PR bodies, PR and issue comments, ticket text,
// board evidence and every export to the observability sink. A guard test (redaction-guard.test.mjs) fails when a
// writer or poster goes around it.
//
// Detection, three sources:
//   1. rules: the high-confidence rules of the pinned secret scanner (betterleaks, gitleaks-compatible rule ids), plus
//      the credential shape the owner's scanner flagged: a name containing key/secret/token/password directly before a
//      hex or base64-like value (`generic-api-key:0123abcd…`, `"apiKey": "…"`);
//   2. the values of the configured token environment variables (any variable named *TOKEN, *SECRET, *PASSWORD, *_KEY,
//      *CREDENTIALS, and the ones the config names);
//   3. every value detected earlier in the run, by this boundary or a tool parser (rememberSecret). Only a SHA-256 of
//      each value is kept, in memory and in the run's state directory (never committed), so a value seen once is
//      redacted wherever it turns up later, even where no rule would match it.
// Each match is replaced with `[redacted:<rule>]`. Values holding the factory's placeholder marker (FAKE_SECRET_MARKER,
// `factoryfake`) are test data and stay.
//
// Redaction never touches what the pipeline computes from records: fingerprints and finding ids carry no credential
// shape (analysis/baseline.mjs), token counts are numbers, hashes and SHAs sit under names without a credential word.

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

export const PLACEHOLDER_MARKER = 'factoryfake';
const MARK = (rule) => `[redacted:${rule}]`;

// Rule ids follow the scanner's (gitleaks / betterleaks default rules).
export const RULES = [
  { id: 'private-key', re: /-----BEGIN[ A-Z0-9_-]{0,100}PRIVATE KEY(?: BLOCK)?-----[\s\S]{16,}?-----END[ A-Z0-9_-]{0,100}PRIVATE KEY(?: BLOCK)?-----/g },
  { id: 'github-pat', re: /\bghp_[0-9A-Za-z]{36}\b/g },
  { id: 'github-fine-grained-pat', re: /\bgithub_pat_[0-9A-Za-z_]{82}\b/g },
  { id: 'github-oauth', re: /\bgho_[0-9A-Za-z]{36}\b/g },
  { id: 'github-app-token', re: /\b(?:ghu|ghs)_[0-9A-Za-z]{36}\b/g },
  { id: 'github-refresh-token', re: /\bghr_[0-9A-Za-z]{36,76}\b/g },
  { id: 'gitlab-pat', re: /\bglpat-[0-9A-Za-z_-]{20,}\b/g },
  { id: 'aws-access-token', re: /\b(?:A3T[A-Z0-9]|AKIA|ASIA|ABIA|ACCA)[A-Z2-7]{16}\b/g },
  { id: 'slack-token', re: /\bxox[abposr]-[0-9A-Za-z-]{10,}\b/g },
  { id: 'stripe-access-token', re: /\b(?:sk|rk)_(?:test|live|prod)_[0-9A-Za-z]{10,99}\b/g },
  { id: 'gcp-api-key', re: /\bAIza[0-9A-Za-z_-]{35}\b/g },
  { id: 'anthropic-api-key', re: /\bsk-ant-(?:api03|admin01)-[0-9A-Za-z_-]{20,}/g },
  { id: 'openai-api-key', re: /\bsk-(?:proj-|svcacct-|admin-)?[0-9A-Za-z_-]{20,}T3BlbkFJ[0-9A-Za-z_-]{20,}/g },
  { id: 'npm-access-token', re: /\bnpm_[0-9A-Za-z]{36}\b/g },
  { id: 'jwt', re: /\bey[A-Za-z0-9]{15,}\.ey[A-Za-z0-9_/\\-]{15,}\.[A-Za-z0-9_/\\-]{10,}={0,2}/g },
  { id: 'azure-storage-key', re: /\bAccountKey=[A-Za-z0-9+/]{40,}={0,2}/g, keep: 'AccountKey=' },
  { id: 'url-credentials', re: /\b([a-z][a-z0-9+.-]{1,20}:\/\/[^\s:@/'"]{1,64}:)([^\s@/'"]{3,128})(@)/gi, group: 2 },
  { id: 'connection-string-password', re: /\b((?:Password|Pwd)\s*=\s*)([^;'"\s<>{}]{4,128})/gi, group: 2 },
  // The credential shape: a name ending in a credential word, an assignment or separator, then a value that looks like
  // one (hex or base64-like, 8+ characters, with letters and digits). `key` alone is not a credential word (ticket keys).
  { id: 'generic-api-key', re: /((?:[A-Za-z0-9_.-]*?)(?:api[_.-]?key|access[_.-]?key|secret[_.-]?key|private[_.-]?key|auth[_.-]?key|encryption[_.-]?key|signing[_.-]?key|client[_.-]?secret|secret|token|passwd|password|pwd|credentials?)s?["']?\s*(?:=>|:=|[:=])\s*["']?)([A-Za-z0-9+/_.~-]{8,}={0,2})/gi, group: 2, check: credentialLike },
];

function entropy(s) {
  const n = new Map();
  for (const c of s) n.set(c, (n.get(c) ?? 0) + 1);
  let h = 0;
  for (const v of n.values()) h -= (v / s.length) * Math.log2(v / s.length);
  return h;
}

function credentialLike(v) {
  if (v.startsWith('[redacted') || v.toLowerCase().includes(PLACEHOLDER_MARKER)) return false;
  if (/^\d+$/.test(v) || /^(true|false|null|undefined|none|required|optional|string|number|boolean|object|redacted)$/i.test(v)) return false;
  if (/^[A-Z][A-Z0-9_]+$/.test(v)) return false; // an environment variable's name, not its value
  if (/^(?:\$\{?|%|<|\{\{)/.test(v)) return false; // a reference or template
  if (/^[a-z]+(?:[._-][a-z]+)*$/i.test(v)) return false; // words: a setting name, a file name stem
  return /[0-9]/.test(v) && /[A-Za-z]/.test(v) && entropy(v) >= 3;
}

// ---- known values -------------------------------------------------------------------------------------------
export const SECRET_ENV_RE = /(?:^|_)(?:TOKEN|SECRET|PASSWORD|PASSWD|API_?KEY|PRIVATE_KEY|ACCESS_KEY|CLIENT_SECRET|CREDENTIALS?|PAT)$/i;
const extraNames = new Set();
export function secretEnvNames(names = []) {
  for (const n of names) if (n) extraNames.add(String(n));
}
function envValues(env) {
  const out = [];
  for (const [k, v] of Object.entries(env ?? {})) {
    if (typeof v !== 'string' || v.length < 8 || v.toLowerCase().includes(PLACEHOLDER_MARKER)) continue;
    if (SECRET_ENV_RE.test(k) || extraNames.has(k)) out.push({ rule: `env:${k}`, value: v });
  }
  return out.sort((a, b) => b.value.length - a.value.length);
}

const sha = (v) => crypto.createHash('sha256').update(v).digest('hex');
const seen = new Map(); // sha -> rule
let seenFileLoaded = null;
const seenFile = () => process.env.FACTORY_REDACT_SEEN || (process.env.PIPELINE_ROOT ? path.join(process.env.PIPELINE_ROOT, '.factory', 'state', 'redact-seen.jsonl') : null);

function loadSeen() {
  const f = seenFile();
  if (!f || seenFileLoaded === f) return;
  seenFileLoaded = f;
  try {
    for (const line of fs.readFileSync(f, 'utf8').split('\n')) {
      if (!line.trim()) continue;
      const r = JSON.parse(line);
      if (r.h) seen.set(r.h, r.rule ?? 'seen');
    }
  } catch {
    // no file yet
  }
}

// A value a scanner matched: kept as a hash for the rest of the run.
export function rememberSecret(value, rule = 'seen') {
  if (typeof value !== 'string' || value.length < 8 || value.toLowerCase().includes(PLACEHOLDER_MARKER) || /^\[redacted/.test(value) || /^REDACTED$/i.test(value)) return;
  loadSeen();
  const h = sha(value);
  if (seen.has(h)) return;
  seen.set(h, rule);
  const f = seenFile();
  if (!f) return;
  try {
    fs.mkdirSync(path.dirname(f), { recursive: true });
    fs.appendFileSync(f, `${JSON.stringify({ h, rule })}\n`, { mode: 0o600 });
  } catch {
    // memory only
  }
}

export function forgetSecretsForTest() {
  seen.clear();
  extraNames.clear();
  seenFileLoaded = null;
}

// ---- redaction ----------------------------------------------------------------------------------------------
// A string with every detected secret replaced; `hits` lists the rules (never the values).
export function redactText(text, { env = process.env } = {}) {
  if (typeof text !== 'string' || text.length < 8) return { text, hits: [] };
  const hits = [];
  let out = text;
  for (const { rule, value } of envValues(env)) {
    if (out.includes(value)) {
      out = out.split(value).join(MARK(rule.startsWith('env:') ? 'env' : rule));
      hits.push(rule);
    }
  }
  for (const r of RULES) {
    r.re.lastIndex = 0;
    out = out.replace(r.re, (...m) => {
      const groups = m.slice(1, -2);
      const value = r.group ? groups[r.group - 1] : m[0];
      if (typeof value !== 'string') return m[0];
      if (r.check && !r.check(value)) return m[0];
      if (!r.check && value.toLowerCase().includes(PLACEHOLDER_MARKER)) return m[0];
      hits.push(r.id);
      rememberSecret(value, r.id);
      if (!r.group) return r.keep ? `${r.keep}${MARK(r.id)}` : MARK(r.id);
      return groups.map((g, i) => (i === r.group - 1 ? MARK(r.id) : g ?? '')).join('');
    });
  }
  loadSeen();
  if (seen.size) {
    out = out.replace(/[^\s"'`<>()[\]{},;]{8,}/g, (tok) => {
      for (const cand of [tok, ...tok.split(/[=:@]/)]) {
        if (cand.length < 8) continue;
        const rule = seen.get(sha(cand));
        if (rule) {
          hits.push(`seen:${rule}`);
          return tok.split(cand).join(MARK(rule));
        }
      }
      return tok;
    });
  }
  return { text: out, hits };
}

export const redact = (text, opts) => redactText(text, opts).text;

// Any value: strings redacted, arrays and plain objects walked (keys kept), everything else as it is.
export function redactValue(value, opts) {
  if (typeof value === 'string') return redact(value, opts);
  if (Array.isArray(value)) return value.map((v) => redactValue(v, opts));
  if (value && typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype) {
    const o = {};
    for (const [k, v] of Object.entries(value)) o[k] = redactValue(v, opts);
    return o;
  }
  return value;
}

// ---- the scan gate on what leaves the machine -----------------------------------------------------------------
export class SecretGateError extends Error {
  constructor(where, hits) {
    super(`secret gate: ${where} still holds ${hits.length} detected secret(s) after redaction (${[...new Set(hits)].join(', ')}); nothing was sent`);
    this.code = 'secret-gate';
    this.hits = hits;
  }
}

// The generic pattern the owner's check uses, over text that is about to leave: `(api-key|secret|token|password)[:=]<value>`.
export const GENERIC_KEY_PATTERN = /\b(?:api[_-]?key|secret|token|password)\s*[:=]\s*["']?([A-Za-z0-9+/_.~-]{8,})/gi;
export function genericHits(text) {
  const out = [];
  GENERIC_KEY_PATTERN.lastIndex = 0;
  for (const m of String(text).matchAll(GENERIC_KEY_PATTERN)) if (credentialLike(m[1])) out.push(m[0].replace(m[1], '…'));
  return out;
}

// Redacts, then scans what is left; anything still detected blocks (thrown, never sent). Returns the redacted value.
export function gate(value, where, opts) {
  const red = redactValue(value, opts);
  const flat = typeof red === 'string' ? red : JSON.stringify(red ?? '');
  const left = [...redactText(flat, opts).hits, ...genericHits(flat)];
  if (left.length) throw new SecretGateError(where, left);
  return red;
}

// ---- writers --------------------------------------------------------------------------------------------------
// The only way records and published text reach a file (the guard test enforces it). Buffers pass unchanged.
export function writeText(file, data, opts) {
  fs.writeFileSync(file, typeof data === 'string' ? redact(data) : data, opts);
}
export function appendText(file, data, opts) {
  fs.appendFileSync(file, typeof data === 'string' ? redact(data) : data, opts);
}

// Wraps every write operation of a provider adapter (host, tracker, sink): its arguments pass the gate. `ops` are the
// contract's write operation ids (`pr.comment`, `tickets.create`); `all` guards every function (custom adapters).
export function guardAdapter(adapter, kind, ops, { all = false } = {}) {
  if (!adapter || typeof adapter !== 'object' || adapter.__secretGate) return adapter;
  const wanted = new Set(ops);
  const walk = (obj, prefix, depth) => {
    if (!obj || typeof obj !== 'object' || depth > 3) return;
    for (const key of Object.keys(obj)) {
      const id = prefix ? `${prefix}.${key}` : key;
      // Accessors are never read here (a tracker's getter may call its service).
      const d = Object.getOwnPropertyDescriptor(obj, key);
      if (!d || !('value' in d)) continue;
      const v = d.value;
      if (typeof v === 'function' && (all || wanted.has(id))) {
        const fn = v;
        obj[key] = function guarded(...args) {
          return fn.apply(this, args.map((a) => gate(a, `${kind} ${id}`)));
        };
      } else if (v && typeof v === 'object' && !Array.isArray(v) && Object.getPrototypeOf(v) === Object.prototype) walk(v, id, depth + 1);
    }
  };
  walk(adapter, '', 0);
  Object.defineProperty(adapter, '__secretGate', { value: true, enumerable: false });
  return adapter;
}

// The text agents get: never write a credential anywhere; refer to it by name or place; use the placeholder.
export const AGENT_SECRET_RULE = [
  '## Secrets (every agent, every CLI)',
  '',
  `Never write a key, token, password or connection string into your output, notes, findings, evidence, plans, tests, commit messages or comments, even one you found in the repository or in a tool's output. Refer to it by its setting name or by file and line ("the value of GH_TOKEN", "appsettings.json:12"). Test data that needs a credential-like value uses the repository's allow-listed placeholder: a value containing \`${PLACEHOLDER_MARKER}\` (for example \`${PLACEHOLDER_MARKER}-0000\`). Do not put a rule or field name containing key, secret, token or password directly before a hex or base64-like string in anything you write. The harness redacts what it detects, but a value it does not know about would leave the machine.`,
].join('\n');

// The harness's own console output (run logs, CLI output that background runs write to their log files) passes the
// boundary too: installed once per process by util.mjs, which every harness module imports.
export function installOutputRedaction(proc = process) {
  if (proc.__outputRedaction) return;
  for (const stream of [proc.stdout, proc.stderr]) {
    const write = stream.write.bind(stream);
    stream.write = (chunk, ...rest) => write(typeof chunk === 'string' ? redact(chunk) : chunk, ...rest);
  }
  Object.defineProperty(proc, '__outputRedaction', { value: true, enumerable: false });
}

// Values the configuration holds under a credential-named setting (a token or key written into the config instead of
// named by its environment variable), and the environment variables the config names as token sources: both are known
// secrets for the rest of the process. Called by the config loader.
const CRED_NAME = /(?:token|secret|password|passwd|api[_-]?key|access[_-]?key|private[_-]?key|client[_-]?secret|credentials?)$/i;
export function registerConfigSecrets(config, depth = 0) {
  if (!config || typeof config !== 'object' || depth > 6) return;
  for (const [k, v] of Object.entries(config)) {
    if (typeof v === 'string') {
      if (/(?:tokenEnv|Env|EnvVar)$/.test(k) && /^[A-Z][A-Z0-9_]+$/.test(v)) secretEnvNames([v]);
      else if (CRED_NAME.test(k) && !/^[A-Z][A-Z0-9_]+$/.test(v) && !/^\$\{?/.test(v)) rememberSecret(v, 'config');
    } else if (v && typeof v === 'object') registerConfigSecrets(v, depth + 1);
  }
}
